  "objectives": [
    {
      "label": "Describe Your Symptoms",
      "description": "Explique que está com coriza e coceira nos olhos há quatro dias."
    },
    {
      "label": "Check the Medication Instructions",
      "description": "Pergunte como tomar o cetirizine e confirme a frequência."
    },
    {
      "label": "Book a Follow-Up",
      "description": "Escolha um horário disponível e marque uma consulta de retorno."
    }
  ],
  "openingLine": "Hi, this is Priya, the nurse at Lakeview Family Clinic. How can I help?",
  "hints": [
    "I have a runny nose and itchy eyes.",
    "It's been bothering me for four days.",
    "How often should I take the cetirizine?",
    "Can I take it with food?",
    "Could I come in Wednesday at 10:30 a.m.?"
  ]
}

